#: Caps on a forwarded `job_update` (the relay does not trust the tenant's).
#: A plan is 2–6 steps plus "Check and merge" / "Write the answer" and any
#: honestly inserted step; twelve leaves room without letting a runaway plan
#: flood the audio socket.
_JOB_FRAME_STEPS_MAX = 12
_JOB_FRAME_SOURCES_MAX = 6
_JOB_FRAME_LABEL_MAX = 120
_JOB_FRAME_PREVIEW_MAX = 240
_JOB_HEX_COLOR = re.compile(r"#[0-9a-fA-F]{6}")


def _job_int(value: Any) -> Optional[int]:
    if isinstance(value, bool):
        return None
    try:
        return int(value)
    except (TypeError, ValueError):
        return None


def task_job_update_frame(ev: Mapping[str, Any], delegation_id: str) -> Optional[dict]:
    """The phone `job_update` for one tenant SSE `job.update`, or None.

    The existing chat keys keep their TYPES (`step` and `name` are strings,
    the counts numbers — the web renders them, and an object in `step` takes
    the chat render down); everything new rides under new keys.  No `channel`
    key, ever: both clients drop a channel they do not own.
    """

    job_id = str(ev.get("job_id") or "")[:64]
    if not job_id:
        return None
    frame: dict[str, Any] = {"type": "job_update", "job_id": job_id}
    name = ev.get("name") or ev.get("title")
    if name:
        frame["name"] = str(name)[:_JOB_FRAME_LABEL_MAX]
    for key in ("job_type", "status", "step", "role", "label", "model"):
        value = ev.get(key)
        if isinstance(value, str) and value:
            frame[key] = value[:_JOB_FRAME_LABEL_MAX]
    for key in ("chat_id", "message_id", "parent_job_id"):
        value = ev.get(key)
        if value:
            frame[key] = str(value)[:64]
    for key in ("total_steps", "completed_steps", "worker_index", "plan_step_index",
                "attempt", "workers_total", "workers_done"):
        value = _job_int(ev.get(key))
        if value is not None and value >= 0:
            frame[key] = value
    color = ev.get("color")
    if isinstance(color, str) and _JOB_HEX_COLOR.fullmatch(color):
        frame["color"] = color
    steps = ev.get("steps")
    if isinstance(steps, list):
        kept = []
        for raw in steps[:_JOB_FRAME_STEPS_MAX]:
            if not isinstance(raw, Mapping):
                continue
            step: dict[str, Any] = {}
            # Scalars keep their type (a step id may be a number); the row is
            # the tenant's `steps_json` shape, never re-projected here.
            # `rev`: the tenant's per-row revision — a retracted answer beat
            # walks a row BACK, and only a changed `rev` makes the phone's
            # rank merge accept it (Phase D, contract-wire-1).
            for key in ("id", "type", "label", "status", "started_at", "completed_at",
                        "duration_ms", "rev"):
                value = raw.get(key)
                if isinstance(value, str) and value:
                    step[key] = value[:_JOB_FRAME_LABEL_MAX]
                elif isinstance(value, (int, float)) and not isinstance(value, bool):
                    step[key] = value
            if step.get("label") or step.get("type"):
                kept.append(step)
        frame["steps"] = kept
    sources = ev.get("sources")
    if isinstance(sources, list):
        kept_sources = []
        for s in sources[:_JOB_FRAME_SOURCES_MAX]:
            if not isinstance(s, Mapping):
                continue
            src = {k: str(s.get(k) or "")[:400] for k in ("title", "url", "domain") if s.get(k)}
            # Wire §2.7 (voice round 2026-10-06, D-T4): the tenant stamps a
            # FETCHED page's own icon on its source.  The key is copied (https
            # only, the tenant's own bound) or the call's job card never shows
            # it — the app reads `sources[].icon` off this frame.
            icon = s.get("icon")
            if isinstance(icon, str) and icon.startswith("https://") and len(icon) <= 400:
                src["icon"] = icon
            kept_sources.append(src)
        frame["sources"] = kept_sources
    preview = ev.get("result_preview")
    if isinstance(preview, str) and preview:
        visible = sanitize_user_visible_answer(preview)[:_JOB_FRAME_PREVIEW_MAX]
        if visible:
            frame["result_preview"] = visible
    frame["task_id"] = delegation_id
    frame["delegation_id"] = delegation_id
    return frame


def task_step_event_frame(ev: Mapping[str, Any], delegation_id: str) -> Optional[dict]:
    """The phone `step_event` for one tenant SSE `step.event` (chat's shape)."""

    kind = ev.get("kind")
    if not isinstance(kind, str) or not kind:
        return None
    frame: dict[str, Any] = {"type": "step_event", "kind": kind[:32]}
    for key in ("job_id", "step_name"):
        value = ev.get(key)
        if value:
            frame[key] = str(value)[:_JOB_FRAME_LABEL_MAX]
    for key in ("step_index", "steps_total", "elapsed_ms"):
        value = _job_int(ev.get(key))
        if value is not None and value >= 0:
            frame[key] = value
    if isinstance(ev.get("final"), bool):
        frame["final"] = ev["final"]
    # D-T3 (5) (voice round 2026-10-06): the tenant's round-START answer beat
    # carries `provisional: true` (a tool call later in the round retracts
    # it).  Forwarded only when the tenant says so — older images send none,
    # and a client that ignores the key reads the beat's `kind`/`final` as
    # before.
    if ev.get("provisional") is True:
        frame["provisional"] = True
    frame["task_id"] = delegation_id
    frame["delegation_id"] = delegation_id
    return frame


def relay_opened_delegation(delegation_id: Any) -> bool:
    """Is this a delegation the relay opened (never named to GPT-Live)?"""

    return str(delegation_id or "").startswith(RELAY_OPENED_PREFIXES)


def reask_mode(why: str) -> str:
    """The reask wording for a `resolve_reask` reason (§3.2-3.3, A4)."""

    if why == "carried_fragment":
        return "fragment"
    if why in {"unconfirmed", "carried_unconfirmed"}:
        return "unconfirmed"
    if why in {"conditional", "carried_conditional"}:
        return "conditional"
    if why in {"own_unheard", "carried_unheard"}:
        return "unheard"
    return ""

# ── R6-4b: the media scope STAMP, a hybrid logical clock ─────────────
# Every ordered media request of one provider session (its caller-turn order
# restarts with each session) carries the session's stamp, so the tenant can
# order a halt and a play from DIFFERENT scopes of one call.  A relay replica's
# wall clock alone is not comparable with another replica's; the only causal
# path between two scopes is the app (scope B exists because the app
# reconnected after scope A), so the stamp is max(wall, app floor + 1, this
# process's last stamp for the user + 1).  No order is ever sent without it.
_SCOPE_STAMP_LIMIT = 2 ** 53
#: user id → the last stamp this process issued (bounded, least recent first).
_LAST_SCOPE_STAMPS: dict[str, int] = {}
_LAST_SCOPE_STAMPS_MAX = 4096


def _scope_wall_ms() -> int:
    """The relay's wall clock in epoch ms (its own seam, so a test can step it)."""

    return int(time.time() * 1000)


def valid_scope_floor(raw: Any) -> int:
    """`config.media_scope_floor_ms` if it is a usable floor, else 0.

    An int (never a bool, never a numeric string), 0 < v < 2**53; anything
    else is ignored rather than trusted.
    """

    if isinstance(raw, bool) or not isinstance(raw, int):
        return 0
    return raw if 0 < raw < _SCOPE_STAMP_LIMIT else 0


def next_scope_stamp(user_id: str, floor: int = 0) -> int:
    """The stamp of a provider session starting NOW for `user_id`.

    Strictly above the app's floor (the newest stamp the app received from any
    replica) and above this process's previous stamp for the user, so a
    reconnect orders after the scope it replaced even when this replica's wall
    clock is behind or stepped backwards.  (A floor of 2**53 - 1 cannot be
    exceeded inside the wire range; the stamp is clamped to it.)
    """

    floor = valid_scope_floor(floor)
    last = _LAST_SCOPE_STAMPS.pop(user_id, 0)
    stamp = max(_scope_wall_ms(), floor + 1 if floor else 0, last + 1 if last else 0)
    stamp = min(stamp, _SCOPE_STAMP_LIMIT - 1)
    _LAST_SCOPE_STAMPS[user_id] = stamp
    while len(_LAST_SCOPE_STAMPS) > _LAST_SCOPE_STAMPS_MAX:
        _LAST_SCOPE_STAMPS.pop(next(iter(_LAST_SCOPE_STAMPS)))
    return stamp

#: What `judge_heard_text` decided about one frame's receipt claim.  Three
#: values and not two, because "no claim was made" and "a claim was made and
#: refused" are different facts about the CLIENT and, more importantly, must
#: produce different writes: neither may resurrect the full generated text, but
#: only one of them is a defect worth a counter.  The single `None` they used to
#: share is exactly how a refused late claim came to look like consent to
#: restore the whole answer.
HEARD_ABSENT = "absent"
HEARD_REFUSED = "refused"
HEARD_ACCEPTED = "accepted"

#: Addendum 4 §3.2 as corrected by the supervisor (2026-09-23 18:16): what the
#: relay KNOWS about whether the caller heard an output epoch — three values,
#: not two.  HEARD and UNHEARD are positive receipts under the existing rules
#: (`_LiveSession.epoch_evidence`); UNKNOWN is the ABSENCE of any receipt (the
#: epoch still open, retired by the relay's own gap timer, aged out of the
#: bounded record, or dropped with the socket).  Absence is evidence of
#: neither: it must never close a request as answered (the old presumption,
#: which silently cleared a request whose text-only answer nobody heard), and
#: never tell the model its answer "did not reach" the caller.
OUTPUT_HEARD = "heard"
OUTPUT_UNHEARD = "unheard"
OUTPUT_UNKNOWN = "unknown"

#: How long a gap-retired output epoch holds its transcript row while it waits
#: for the client's receipt, in milliseconds.  See `_LiveSession.park_spoken`
#: for what the window is FOR and `spoken_settle_s` for why 2500 and not more.
#:
#: This belongs in `app/config.py` as `voice_live_spoken_settle_ms`, next to
#: `voice_live_output_epoch_gap_ms`, so a deployment can tune it — and it is a
#: module constant here only because that file is not this change's to edit.
#: Deliberately NOT reached for through a defaulted settings lookup in the
#: meantime.  `test_every_settings_name_the_relay_reads_actually_exists` exists
#: because a settings name this relay reads and `Settings` never declares is
#: silently the literal default for ever — reading the field before it exists
#: would make this the exact bug that guard was written to catch, and the guard
#: reads the raw source, so even naming the lookup shape in a comment trips it.
#: When the field lands, `spoken_settle_s` is the one line that changes.
_SPOKEN_SETTLE_MS = 2500

#: `_LiveSession.tick_loop` after a tick that raised: the first retry waits
#: this long, each consecutive failure doubles it up to the cap, and the
#: traceback is logged for the first failure and every Nth after it. A
#: successful tick resets all three.
_TICK_FAILURE_BACKOFF_S = 0.05
_TICK_FAILURE_BACKOFF_MAX_S = 1.0
_TICK_FAILURE_LOG_EVERY = 50

#: P1 (2026-10-02 call) — the UPLINK KEEPER's fixed shape (see
#: `_LiveSession.uplink_keeper_loop`).  GPT-Live's input is PCM16 mono at
#: 24 kHz (`build_session_start`), so one 100 ms chunk of digital silence is
#: 2,400 zero samples = 4,800 zero bytes.  It is sent once per 100 ms of wall
#: time — real-time pace, never a burst — and only after the phone has sent no
#: audio for 500 ms, so it can only ever fill a gap the phone left.
_UPLINK_KEEPER_CHUNK_S = 0.1
_UPLINK_KEEPER_IDLE_S = 0.5
_UPLINK_KEEPER_SILENCE_B64 = base64.b64encode(b"\x00" * 4800).decode("ascii")

#: D-P1 (2026-10-05 call): a DIRECT reply owed to a closed caller request is
#: tracked from the close until output, a delegation or a newer request — and
#: never longer than this: the app hands the request off by then (its strand
#: 12 s + replay 12 s + hold 36 s), and an owed reply holds `thinking` and the
#: keeper, so it must not outlive every party still waiting on it.
_REPLY_PENDING_MAX_S = 60.0
#: The relay's one "stop talking" note. Permanent session state like every
#: append, so it scopes itself to the reply it interrupts (D-P1).
_STOP_INSTRUCTION = (
    "Stop speaking now; this applies to the reply in progress only. "
    "Do not acknowledge this instruction."
)
#: A reply the relay DROPPED (caller resumed, interrupt fence, spoken over) is
#: asked for again by the relay after this long with no output and no
#: delegation for its request — long enough for the model's own answer to the
#: resumed words (or a late delegation) to land first.
_DROPPED_REPLY_GRACE_S = 2.0
#: Every reask the relay or the app files, per caller turn, in total.  Real
#: since voice round 2026-10-06 (D-R1 (b)): it used to be read only after a
#: `once_per_turn` fence that had already refused every second ask, so it
#: could never be reached.  Each reask is a PERMANENT session note (D11), so
#: "asked again until answered" is the reply backstop, never a third note.
_REASK_MAX_PER_TURN = 2
#: D-R1 (a)/(c): how many ACCEPTED relay reasks a direct reply gets before the
#: reply backstop decides (when the backstop is on).  One: the note either
#: works within one `voice_live_reply_regen_after_s` or the agent is asked.
_REPLY_REGEN_ATTEMPTS = 1
#: D-R1 (a): a refused regen (output still open, input still, a decision on
#: its way) is judged again this much later — never spent by the refusal.
_REPLY_RETRY_S = 0.5
#: Phase D2 (correctness-relay-6): the reply backstop's re-decision interval
#: while another relay backstop (research / play / media) is ARMED for the
#: owed turn.  That backstop either fires — the turn is then claimed and its
#: delegation answers it — or declines (`stale`, `no_subject`, the play's
#: `extended` stand-down) and drops the turn from its maps; only re-asking
#: after it decides tells the two apart.  Phase D3: `already_running` claims
#: the turn for the running search, and a `retracted` play ends the owed reply.
_REPLY_ARMED_RETRY_S = 1.0
#: The `reply_backstop_hold` reasons that mean "another backstop owns it for
#: now" — a wait, never a verdict.
_REPLY_ARMED_HOLDS = frozenset(("research_armed", "play_armed", "media_armed"))
#: D-R1 (g): an output epoch opening this soon after a delegation was created
#: for a caller turn is that delegation's ACKNOWLEDGEMENT ("let me check") —
#: it answers that turn, never an older one still owed a reply.
_DELEGATION_ACK_WINDOW_S = 1.0
#: D-R1 (h): fail-closed bound of the held (deferred) output buffer — a normal
#: guarded pause is a few hundred audio chunks.
_DEFERRED_OUTPUT_MAX_BYTES = 4 * 1024 * 1024
#: D-P12: the terminal states a `recover_delegations` task may carry, and the
#: `last_outcomes` outcome each rebuilds. Keyed on the WIRE vocabulary the app
#: holds — its TaskState, which `send_delegation` maps cancelled/superseded to
#: `canceled` and expired to `failed` — plus the legacy phase spellings. An
#: unread `canceled` used to leave the card's Retry answering `unknown_task`.
_RECOVERED_TERMINAL_OUTCOMES = {
    "completed": "ok", "failed": "failed", "empty": "empty",
    "canceled": "cancelled", "cancelled": "cancelled", "expired": "failed",
}

#: An output epoch longer than an hour is not a number a phone can honestly
#: report; it is a clock fault or a hostile frame.  `played_ms` is clamped
#: rather than rejected because the epoch still closed and the row still has
#: to be written.
_PLAYED_MS_CEILING = 3_600_000

#: Wire bound on `heard_text`, in UTF-16 code units (the unit the sender
#: counts in).  Ten thousand units is far past any single spoken epoch and
#: keeps one malformed frame from carrying a megabyte into the queue.
_HEARD_TEXT_MAX_UNITS = 10_000


def _played_ms_value(raw: Any) -> Optional[int]:
    """Parse a client-reported playback position, or None.

    `isinstance(v, (int, float))` alone accepted three things it should not:
    `True` (a bool IS an int in Python, and `int(True)` is a millisecond
    position of 1), and NaN/Infinity — which `json.loads` accepts by default
    and on which `int()` raises, so one malformed frame took down the whole
    client loop rather than one field.
    """

    if isinstance(raw, bool) or not isinstance(raw, (int, float)):
        return None
    if isinstance(raw, float) and raw != raw:      # NaN, the one value != itself
        return None
    if raw in (float("inf"), float("-inf")):
        return None
    return max(0, min(int(raw), _PLAYED_MS_CEILING))


def resolve_live_voice(requested: Optional[str], default: str = "marin") -> str:
    """Return a GPT-Live voice, never a Realtime-only voice name.

    Existing clients currently request names such as ``shimmer``.  Silently
    forwarding those names makes session.start fail, so rollout uses the
    configured Live default until clients expose the new Live voice catalogue.
    """

    candidate = (requested or "").strip().lower()
    if candidate in LIVE_VOICES:
        return candidate
    configured = (default or "marin").strip().lower()
    return configured if configured in LIVE_VOICES else "marin"


def build_session_start(
    *,
    instructions: str,
    voice: str = "marin",
    model: str = LIVE_MODEL,
    history: Optional[Iterable[Mapping[str, str]]] = None,
    event_id: str = "toup-live-start",
) -> dict[str, Any]:
    """Build the first (and only valid first) event on a Live WebSocket.

    ``history`` is intentionally text-only and bounded by the caller.  Live
    accepts at most 128 messages / 8,192 combined tokens; the relay must apply
    its normal history budget before calling this helper.
    """

    session: dict[str, Any] = {
        "model": model,
        "instructions": instructions,
        "audio": {
            "format": {"type": "audio/pcm", "rate": 24000},
            "output": {"voice": resolve_live_voice(voice)},
        },
        "delegation": {"type": "client"},
        # Toup owns durable chat history.  Avoid provider-side recording/state
        # retention unless a separately reviewed resume design enables it.
        "store": False,
    }
    if history:
        items = []
        for row in history:
            role = str(row.get("role") or "")
            text = str(row.get("content") or "")
            if role not in {"developer", "user", "assistant"} or not text:
                continue
            content_type = "output_text" if role == "assistant" else "input_text"
            items.append({
                "type": "message",
                "role": role,
                "content": [{"type": content_type, "text": text}],
            })
        if items:
            session["input"] = items[-128:]
    return {"type": "session.start", "event_id": event_id, "session": session}


def audio_append(audio_b64: str) -> dict[str, str]:
    """Translate one ordered PCM16 chunk to the GPT-Live wire event."""

    return {"type": "session.input_audio.append", "audio": audio_b64}


def close_session(event_id: str = "toup-live-close") -> dict[str, str]:
    """Request a graceful close so final cumulative usage can be received."""

    return {"type": "session.close", "event_id": event_id}


def commentary_append(
    delegation_id: str,
    content: str,
    *,
    event_id: str,
) -> dict[str, Any]:
    """Return verified AgentRunner output for GPT-Live to say aloud."""

    if not delegation_id:
        raise ValueError("delegation_id is required")
    content = (content or "").strip()
    if not content:
        raise ValueError("content is required")
    return {
        "type": "session.commentary.append",
        "event_id": event_id,
        "delegation_id": delegation_id,
        "content": content,
    }


def instructions_append(content: str, *, event_id: str) -> dict[str, Any]:
    """Append trusted behavioral guidance to an active Live session."""

    content = (content or "").strip()
    if not content:
        raise ValueError("content is required")
    return {
        "type": "session.instructions.append",
        "event_id": event_id,
        "delegation_id": None,
        "content": content,
    }


def thinking_append(
    content: str,
    *,
    event_id: str,
    delegation_id: Optional[str] = None,
) -> dict[str, Any]:
    """Facts the model may use later without speaking them on arrival."""

    content = (content or "").strip()
    if not content:
        raise ValueError("content is required")
    return {
        "type": "session.thinking.append",
        "event_id": event_id,
        "delegation_id": delegation_id,
        "content": content,
    }


# ── Language: what the caller just spoke ──────────────────────────────
# The relay must never author an English sentence for the user.  Where it has
# no choice but to produce words (a commentary line GPT-Live will paraphrase),
# it picks them from this two-entry table.  Everything aimed at the CLIENT is a
# code the client localises.

_ARABIC_SCRIPT = re.compile(r"[؀-ۿݐ-ݿﭐ-﷿ﹰ-﻿]")


def detect_reply_language(text: str) -> str:
    """'fa' when the utterance is written in Perso-Arabic script, else 'en'.

    Deliberately crude and local: this only chooses which of two relay lines to
    speak and which one-line directive to append to a delegated turn.  The real
    language policy lives in the session instructions, where the model can see
    the whole turn.
    """

    return "fa" if _ARABIC_SCRIPT.search(text or "") else "en"


