def relay_line(key: str, lang: str, **fmt: Any) -> str:
    """One short sentence from the fixed table, in the caller's language."""

    table = _RELAY_LINES.get(key) or {}
    template = table.get(lang if lang in table else "en", "")
    if not template:
        return ""
    try:
        return template.format(**fmt)
    except (KeyError, IndexError):
        return template


#: `ws_realtime.VoiceThinkError.reason` → the typed failure a delegation ends
#: with: the relay line every caller hears and, for a client that negotiated
#: FEATURE_TYPED_TASK_FAILURES, the code its terminal frame and error frame
#: carry.  Every other reason (`agent_error`, `agent_incomplete`) stays
#: `delegation_failed`: the relay claims only the categories it can prove.
_TYPED_THINK_FAILURES = {
    "agent_unreachable": "delegation_unreachable",
    "agent_timeout": "delegation_timeout",
}
TYPED_FAILURE_CODES = frozenset(_TYPED_THINK_FAILURES.values())


def typed_think_failure(reason: Any) -> str:
    """The typed failure code (and relay-line key) for a think failure's
    reason, or "" when it stays `delegation_failed`."""

    return _TYPED_THINK_FAILURES.get(str(reason or ""), "")


# ── Spoken progress labels (R2 §E) ────────────────────────────────────
# What the relay may SAY about a running step.  Keyed by the kind of the tool
# that actually started — never its display title (English only, and the
# spoken Persian status line used to read "Searching the web" aloud) and never
# its arguments (contract §7: a raw query is not a progress label).  A tool
# with no entry here is spoken as generic progress, with no label at all.
_PROGRESS_TOOL_KINDS: dict[str, str] = {
    "web_search": "search",
    "web_fetch": "read",
    "browser": "read",
    "read_file": "files",
    "write_file": "files",
    "edit_file": "files",
    "memory_search": "memory",
    "recall_day": "memory",
}

_PROGRESS_LABELS: dict[str, dict[str, str]] = {
    "search": {"en": "Searching the web", "fa": "در حال جستجو در وب"},
    "read": {"en": "Reading a page", "fa": "در حال خواندن یک صفحه"},
    "files": {"en": "Going through your files", "fa": "در حال بررسی فایل‌ها"},
    "memory": {"en": "Checking what I remember", "fa": "در حال مرور یادداشت‌ها"},
}


def progress_kind(tool_name: str) -> str:
    """The spoken-progress kind of a tool's RAW name, or "" for generic."""

    name = str(tool_name or "")
    if name.startswith("browser"):
        return "read"
    return _PROGRESS_TOOL_KINDS.get(name, "")


def progress_label(kind: str, lang: str) -> str:
    """The localized label for a progress kind; "" when there is none."""

    table = _PROGRESS_LABELS.get(kind or "") or {}
    return table.get(lang if lang in table else "en", "")


#: Voice round 2026-10-07 (D-R4 (2)): how long a task of each PLAN kind is
#: expected to run, end to end (the 10-07 call: research 11–34 s, an agent play
#: 12 s, a tool-less answer 4 s).  A progress line is never spoken within
#: `voice_live_progress_min_remaining_s` of this — a line a second before the
#: result is a line the result waits behind.  Unvalidated against the 10-07
#: tenant research budget (critic U11): every suppression logs `elapsed=` and
#: `expected=` so the re-recording can tune it.  Phase D2 ruling 52: a
#: connector read is expected at 20 s — mapped to "generic" (12 s) its whole
#: tool-line window (6–12 s) sat inside the near-finish window and it could
#: never speak; and a task PAST its expected end is overdue, not near it
#: (`progress_suppression`).
_PROGRESS_EXPECTED_S: dict[str, float] = {
    "search": 20.0, "media": 8.0, "connector": 20.0, "generic": 12.0,
}
#: The model-facing note's own marker (D-R4 (2)): the model voiced the 10-07
#: call's notes on its own («همین الان دارم یه صفحه رو دقیق می‌خونم …»).
_PROGRESS_NOTE_SILENT = "This is silent context: do not mention it unless the caller asks."


def progress_expected_total_s(kind: str) -> float:
    """The expected end-to-end duration of a task of plan kind `kind`."""

    return _PROGRESS_EXPECTED_S.get(kind or "", _PROGRESS_EXPECTED_S["generic"])


# ── Append budgeting: the contract is TOKENS, not characters ──────────

def estimate_tokens(text: str) -> int:
    """Conservative, script-aware token estimate for a Live append.

    The provider's limit is 500 tokens per append.  A flat 350-character cap
    was 3-6x tighter than that and split ordinary answers into two independently
    paraphrased halves, which is the mechanical half of "it stops mid-sentence
    and changes subject".  Persian carries ~2 bytes per character in UTF-8, so
    the byte term is what keeps a non-Latin answer honest.
    """

    text = text or ""
    if not text:
        return 0
    return max(len(text) // 4, len(text.encode("utf-8")) // 3, 1)


_SENTENCE_END = re.compile(r"(?<=[.!?؟。！？۔])\s+")


def split_for_append(text: str, max_tokens: int = 450) -> list[str]:
    """Split text into append-sized chunks on sentence boundaries, in order.

    Never drops or reorders content.  Falls back to a whitespace cut, and then
    to a hard cut, so a single unbroken blob still ships.
    """

    text = (text or "").strip()
    if not text:
        return []
    if estimate_tokens(text) <= max_tokens:
        return [text]

    pieces = [p for p in _SENTENCE_END.split(text) if p.strip()]
    chunks: list[str] = []
    current = ""
    for piece in pieces:
        candidate = (current + " " + piece).strip() if current else piece
        if current and estimate_tokens(candidate) > max_tokens:
            chunks.append(current)
            current = piece
        else:
            current = candidate
    if current:
        chunks.append(current)

    # A single sentence can still exceed the budget (a wall of text with no
    # punctuation).  Cut those on whitespace rather than dropping them.
    out: list[str] = []
    for chunk in chunks:
        while estimate_tokens(chunk) > max_tokens:
            # Characters are the only unit a slice can use; derive the width
            # from the same estimator so the two never disagree.
            width = max(1, int(len(chunk) * max_tokens / max(1, estimate_tokens(chunk))))
            cut = chunk.rfind(" ", 0, width + 1)
            if cut < width // 2:
                cut = width
            out.append(chunk[:cut].strip())
            chunk = chunk[cut:].strip()
        if chunk:
            out.append(chunk)
    return [c for c in out if c]


def split_commentary(text: str, max_tokens: int = 450) -> list[str]:
    """Bound client-delegation updates below Live's 500-token append limit."""

    return split_for_append(text, max_tokens)


# ── Instructions surgery (SUPERVISOR_DECISIONS §6) ────────────────────
# The personalized voice context is shared with the Realtime path and describes
# a function-calling surface that does not exist on the Live wire.  Until the
# agent image can render a Live variant (`live: bool` on the voice-context
# request), the relay strips those paragraphs itself.  This is the GUARANTEE:
# it runs on platform-api, so it ships without a canary agent roll.
#
# Matched by literal openings, pinned by test.  The four Realtime-only
# paragraphs are `navigate_to`, terminal access, the `think` tool and screen
# share; the two companion lines are orphans of the same paragraphs and leaving
# them behind would still tell the model to call a tool it does not have.
