#: D-R1 (e) — FALLBACKS ONLY.  The promise reader (`action_claim_evidence`)
#: and its reask wording (`_REASK_PROMISE_LINES`) belong to the media lane
#: (D-R3); this lane wires the STATE.  Both are read by NAME at call time
#: (`_promise_reader`, `_promise_lines`), so the media lane's module-level
#: definitions supersede these with no edit here; on their own these read
#: nothing as a promise, which leaves promise mode inert.
def _action_claim_evidence_fallback(_text: str) -> bool:
    return False


_REASK_PROMISE_LINES_FALLBACK = {
    "en": (
        "You told the caller «{said}» about «{words}», but you did not delegate "
        "it, so nothing is happening. Delegate it now, and do not say it is done."
    ),
    "fa": (
        "به تماس‌گیرنده گفتی «{said}» دربارهٔ «{words}»، ولی آن را واگذار نکردی، "
        "پس هیچ کاری انجام نمی‌شود. همین حالا واگذارش کن و نگو که انجام شده."
    ),
}


def promise_media_evidence(text: str) -> bool:
    """D-R1 (e): does this caller turn ask for play/media at all?  Promise
    mode is scoped to media/action asks (critic R3): an «باشه» to a question
    is an answer, an «باشه» to «یه آهنگ پخش کن» with nothing delegated is not.
    Reads the media lane's `play_request_evidence` by name when it exists."""

    reader = globals().get("play_request_evidence")
    if callable(reader):
        try:
            ask, is_play = reader(text)
        except Exception:  # noqa: BLE001 - a reader never breaks the ladder
            ask, is_play = None, False
        if ask is not None or is_play:
            return True
    if detect_media_control(text) is not None:
        return True
    return _media_request(text) is not None


def _promise_reader() -> Callable[[str], bool]:
    reader = globals().get("action_claim_evidence")
    return reader if callable(reader) else _action_claim_evidence_fallback


def _promise_lines() -> Mapping[str, str]:
    lines = globals().get("_REASK_PROMISE_LINES")
    return lines if isinstance(lines, Mapping) and lines else _REASK_PROMISE_LINES_FALLBACK


_REASK_RESPONSE_WAIT_S = 12.0
#: D-P3: how long an armed research backstop may wait for a decision still on
#: its way (a pending provider delegation, the caller still talking) before it
#: is dropped as stale rather than fired on words that moved on.
_RESEARCH_BACKSTOP_MAX_WAIT_S = 15.0
#: D-R3: how long an armed PLAY waits for a provider delegation decided at or
#: after its words (or for the caller to finish) before it plays anyway — the
#: brief's "a play starts within ~3 s".
_PLAY_BACKSTOP_MAX_WAIT_S = 3.0
#: D-R4 (4): how long an armed "what's playing" answer waits for a provider
#: delegation decided at/after the turn (Hook A answers that one) or for the
#: caller to finish, before it is dropped as stale.
_MEDIA_STATUS_MAX_WAIT_S = 1.5
_DURABLE_CANCEL_POLL_S = 1.5
#: The durable Stop bit lives on the tenant's voice job, which it opens only
#: at the agent's first planned tool round, so the cancel watch reads nothing
#: before a tool starts — or before this long with no tool frames at all (the
#: blocking agent-turn path relays none) …
_DURABLE_CANCEL_NO_TOOL_WAIT_S = 10.0
#: … and each failed read doubles its next wait, up to this, instead of
#: hitting a stalled tenant every 1.5 s (2026-10-02: every read timed out).
_DURABLE_CANCEL_POLL_MAX_S = 10.0
_DELEGATION_RECOVERY_POLL_S = 1.5
_DELEGATION_TERMINAL_TRAIL_GRACE_S = 5.0
_DELEGATION_STATUS_OUTAGE_S = 10.0
# An open output epoch with no provider delta for this long has missed its
# normal gap rotation. `speak()` retires that epoch before appending the
# recovered answer. The user's own open utterance still blocks speech.
_RECOVERED_OUTPUT_QUIET_S = 2.0


def reask_instruction(
    words: str, lang: str, *, preferred: bool = False, mode: str = "", after: str = "",
    fragment: str = "",
) -> str:
    """The one self-scoping instruction an accepted reask sends.

    ``mode``: "" (plain, unchanged), ``"unheard"`` (its own answer was
    generated but never heard), ``"conditional"`` (addendum 4 §3.3),
    ``"unconfirmed"`` (its own answer was sent but no receipt ever said
    whether it was heard — supervisor 18:16; also conditional on the wire) or
    ``"fragment"`` (addendum 5 A4: the call dropped mid-utterance and nothing
    older is owed — ``words`` are the unfinished words, never executed).
    ``fragment``: with any other mode, the unfinished words the call dropped
    on AFTER this request (A4) — the instruction truthfully adds that the
    caller was cut off and asks the model to have them finish.
    """

    how = "in English" if preferred else "in the language of these words"
    if mode == "promise":
        # D-R1 (e): the model CLAIMED the action («دارم پخش می‌کنم») and
        # delegated nothing; ``after`` carries what it said.
        table = _promise_lines()
        template = table.get("fa" if lang == "fa" else "en") or table.get("en") or ""
        try:
            return template.format(words=words, said=after, how=how, after=after)
        except (KeyError, IndexError):
            return template
    if mode == "fragment":
        table = _REASK_FRAGMENT_LINES
        if lang == "fa":
            return table["fa"].format(fragment=words)
        return table["en"].format(fragment=words, how=how)
    if mode == "conditional":
        table = _REASK_CONDITIONAL_LINES
    elif mode == "unconfirmed":
        table = _REASK_UNCONFIRMED_LINES
    elif mode == "unheard":
        table = _REASK_UNHEARD_LINES
    else:
        table = _REASK_LINES
    if lang == "fa":
        content = table["fa"].format(words=words, after=after)
    else:
        content = table["en"].format(words=words, how=how, after=after)
    if fragment:
        tail = _REASK_FRAGMENT_TAIL["fa" if lang == "fa" else "en"]
        content += tail.format(fragment=fragment)
    return content


def is_app_note(text: str) -> bool:
    """Is this `inject_text` a note the app wrote rather than a replay?

    Structural, not lexical: the app's notes are wholly bracketed, and a
    replayed request never is — ASR produces no literal brackets from speech,
    and the app strips bracketed annotation runs (`stripSpeechAnnotations`)
    before it ever holds a turn's text for replay.
    """

    text = (text or "").strip()
    return len(text) >= 3 and text[0] == "[" and text[-1] == "]"


def reask_key(text: str) -> str:
    """The comparison form a legacy (text-only) reask is resolved by.

    The app replays `stripSpeechAnnotations(final transcript)`; the relay holds
    the raw turn text.  Canonicalized the same way on both sides, then case-,
    diacritic-, ZWNJ- and punctuation-folded, the two are equal.
    """

    canonical = canonical_spoken_text(text) or str(text or "")
    return " ".join(w for w in _TOKEN_SPLIT.split(_normalize(canonical)) if w)


def _epoch_lang(closed: Any) -> str:
    """An epoch's script language as a CODE for a log line (F4) — never text."""

    text = str(getattr(closed, "text", "") or "")
    return detect_reply_language(text) if text.strip() else "-"


# The caller's explicit reply language, per DB session: survives a REPAIR of
# the call inside this process.  Same best-effort, per-process contract as the
# accepted ledger below — an optimisation across replicas, never a correctness
# input; across processes the app re-states it (`language_preference`, addendum
# 8), because no shared store exists: the only per-session record is the
# tenant Conversation's `metadata_json`, which the relay can only replace
# wholesale (there is no merge route, and `_vps_api` speaks GET/POST) while the
# tenant's context manager keeps its compaction summaries and promotion cursor
# in the same column.
#
# Scope (F45): ONE CALL, repairs included — not the rest of the day.  A DB
# session is a whole local day of calls, so keyed on it alone a "speak English"
# said in the morning answered every Persian word of an evening call in
# English, invisibly to TF132, and only on the replica that happened to hear it.
# A socket that ends marks the entry released; a new socket honours it only
# within `_LANGUAGE_PREF_REPAIR_S` of that (a repair), and a socket that opens
# while the previous one is still alive always does.
_LANGUAGE_PREF_BY_SESSION: dict[str, tuple[str, str]] = {}
_LANGUAGE_PREF_LRU: list[str] = []
_LANGUAGE_PREF_RELEASED: dict[str, float] = {}
_LANGUAGE_PREF_OWNER: dict[str, object] = {}
_LANGUAGE_PREF_REPAIR_S = 60.0


def remember_language_pref(db_session_id: str, lang: str, source: str) -> None:
    if not db_session_id:
        return
    # Written by a live socket: held, not released.
    _LANGUAGE_PREF_RELEASED.pop(db_session_id, None)
    if db_session_id in _LANGUAGE_PREF_LRU:
        _LANGUAGE_PREF_LRU.remove(db_session_id)
    if not lang:
        _LANGUAGE_PREF_BY_SESSION.pop(db_session_id, None)
        return
    _LANGUAGE_PREF_BY_SESSION[db_session_id] = (lang, source)
    _LANGUAGE_PREF_LRU.append(db_session_id)
    while len(_LANGUAGE_PREF_LRU) > 64:
        evicted = _LANGUAGE_PREF_LRU.pop(0)
        _LANGUAGE_PREF_BY_SESSION.pop(evicted, None)
        _LANGUAGE_PREF_RELEASED.pop(evicted, None)
        _LANGUAGE_PREF_OWNER.pop(evicted, None)


def release_language_pref(db_session_id: str, owner: object) -> None:
    """The socket that holds this DB session's preference ended.

    Only its OWNER releases it: a repair socket that opened while this one was
    still tearing down already holds the entry, and marking it released would
    start the clock on a call that is still going.
    """

    if not db_session_id or _LANGUAGE_PREF_OWNER.get(db_session_id) is not owner:
        return
    _LANGUAGE_PREF_OWNER.pop(db_session_id, None)
    if db_session_id in _LANGUAGE_PREF_BY_SESSION:
        _LANGUAGE_PREF_RELEASED[db_session_id] = time.monotonic()


def start_language_pref(
    db_session_id: str, pin: Optional[str], *,
    owner: object = None, repair_s: Optional[float] = None,
) -> tuple[str, str]:
    """The preference a new socket starts with: (lang, source) or ("", "").

    A preference the caller STATED on this DB session (spoken, or the app's
    frame) outranks the URL pin, because the pin is re-sent unchanged on every
    connect — honouring it over "speak English" would undo the caller's request
    on the first network blip.  A stored preference that came from a pin is
    only as current as the pin, so the pin replaces it and its absence clears it.

    A stated preference is honoured only for a REPAIR of the call that stated
    it (see the scope note above): its socket is still open, or ended no more
    than `repair_s` ago.  Past that it is a later call, which starts mirroring.
    """

    key = db_session_id or ""
    if key and owner is not None:
        _LANGUAGE_PREF_OWNER[key] = owner
    window = _LANGUAGE_PREF_REPAIR_S if repair_s is None else float(repair_s)
    pin = pin if pin in _LANGUAGE_DISPLAY else ""
    stored = _LANGUAGE_PREF_BY_SESSION.get(key)
    if stored and stored[1] != "pin":
        released = _LANGUAGE_PREF_RELEASED.get(key)
        if released is None or time.monotonic() - released <= window:
            _LANGUAGE_PREF_RELEASED.pop(key, None)
            return stored
        logger.info(
            "[LIVE] language preference expired with its call lang=%s source=%s session=%s",
            stored[0], stored[1], key[:8],
        )
    remember_language_pref(db_session_id, pin, "pin")
    return (pin, "pin") if pin else ("", "")


# The newest caller turn a socket ended WITHOUT answering, per DB session
# (F44).  TF132 replays a question stranded by a socket drop as a bare
# `inject_text` on the repaired socket; the relay's own verdict about that turn
# (no task, no output epoch, not re-asked) died with the old socket, so the new
# one could only drop the replay — silently, to a phone showing "re-asking".
# Same best-effort, per-process contract as the stores above: a reconnect that
# lands on another replica falls back to the hand-off.  Popped by the next
# socket, so a turn is carried once.
_STRANDED_BY_SESSION: dict[str, dict] = {}
_STRANDED_TTL_S = 120.0


def remember_stranded_turn(db_session_id: str, record: Optional[dict]) -> None:
    if not db_session_id:
        return
    _STRANDED_BY_SESSION.pop(db_session_id, None)
    if record:
        _STRANDED_BY_SESSION[db_session_id] = dict(
            record, at=float(record.get("at") or time.monotonic()),
        )
        while len(_STRANDED_BY_SESSION) > 64:
            _STRANDED_BY_SESSION.pop(next(iter(_STRANDED_BY_SESSION)))


def take_stranded_turn(db_session_id: str) -> Optional[dict]:
    record = _STRANDED_BY_SESSION.pop(db_session_id or "", None)
    if not record or time.monotonic() - float(record.get("at") or 0.0) > _STRANDED_TTL_S:
        return None
    return record


